function validate([moveTime]) {
  if (!Array.isArray(moveTime) || moveTime.length < 2 || moveTime.length > 50) return 'moveTime needs 2 to 50 rows.';
  if (!Array.isArray(moveTime[0]) || moveTime[0].length < 2 || moveTime[0].length > 50) return 'Each row needs 2 to 50 rooms.';
  if (moveTime.some(row => !Array.isArray(row) || row.length !== moveTime[0].length)) return 'All rows must have the same length.';
  if (moveTime.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000))) return 'Each moveTime value is a whole number from 0 to 10^9.';
  return null;
}

