function minTimeToReach(moveTime) {
  const rows = moveTime.length;
  const cols = moveTime[0].length;
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const heap = [];

  const swap = (i, j) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };
  const push = (entry) => {
    heap.push(entry);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      swap(i, parent);
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let smallest = i;
        for (const child of [2 * i + 1, 2 * i + 2]) {
          if (child < heap.length && heap[child][0] < heap[smallest][0]) smallest = child;
        }
        if (smallest === i) break;
        swap(i, smallest);
        i = smallest;
      }
    }
    return top;
  };

  dist[0][0] = 0;
  push([0, 0, 0]);
  while (heap.length > 0) {
    const [time, row, col] = pop();
    if (row === rows - 1 && col === cols - 1) {
      return time;
    }
    if (time > dist[row][col]) {
      continue;
    }
    for (const [dr, dc] of directions) {
      const nextRow = row + dr;
      const nextCol = col + dc;
      if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
        continue;
      }
      const arrival = Math.max(time, moveTime[nextRow][nextCol]) + 1;
      if (arrival < dist[nextRow][nextCol]) {
        dist[nextRow][nextCol] = arrival;
        push([arrival, nextRow, nextCol]);
      }
    }
  }
  return dist[rows - 1][cols - 1];
}

