function minTimeToReach(moveTime) {
  // Relax every room's neighbours over and over until no arrival time improves (a Bellman-Ford style fixed point).
  const n = moveTime.length, m = moveTime[0].length;
  const reach = moveTime.map(row => row.map(() => Infinity));
  reach[0][0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < m; j++) {
        if (reach[i][j] === Infinity) continue;
        for (const [x, y] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]]) {
          if (x < 0 || y < 0 || x >= n || y >= m) continue;
          const t = Math.max(reach[i][j], moveTime[x][y]) + 1;
          if (t < reach[x][y]) { reach[x][y] = t; changed = true; }
        }
      }
    }
  }
  return reach[n - 1][m - 1];
}

