function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const rows = large ? 50 - pick(4) : 2 + pick(3);
  const cols = large ? 50 - pick(4) : 2 + pick(3);
  const style = pick(5);
  const wall = large ? 1000000 : 40;
  const cell = (i, j) => {
    if (style === 0) return pick(11);
    if (style === 1) return pick(1000000001);
    if (style === 2) return rand() < 0.6 ? 0 : 1 + pick(wall);
    if (style === 3) return Math.max(0, 2 * (i + j) + pick(5) - 2);
    return rand() < 0.1 ? pick(1000000001) : 0;
  };
  return [Array.from({ length: rows }, (_, i) => Array.from({ length: cols }, (_, j) => cell(i, j)))];
}
